// Edit Distance Wavefront — Algorithms, route: jsx
// Source: original:essay/dp-wavefront
//
// Self-contained: every local import is inlined below. Requires only react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useEffect, useMemo, useState } from 'react';

// ---- inlined from editdistance ----
/**
 * Edit distance between INTENTION and EXECUTION — the classic pair: a shared TION tail
 * of matches behind five substitutions, distance 5. Fully deterministic: the DP matrix,
 * its anti-diagonal fill order, and a diagonal-preferring traceback with the alignment
 * it spells out.
 */

const WORD_A = 'INTENTION';
const WORD_B = 'EXECUTION';

const m = WORD_A.length;
const n = WORD_B.length;

const DP_ROWS = m + 1;
const DP_COLS = n + 1;
/** Anti-diagonals d = i + j run 0 .. m + n. */
const WAVE_COUNT = m + n + 1;

const dp: number[][] = Array.from({ length: m + 1 }, () => new Array<number>(n + 1).fill(0));
for (let i = 0; i <= m; ++i) dp[i][0] = i;
for (let j = 0; j <= n; ++j) dp[0][j] = j;
for (let i = 1; i <= m; ++i)
  for (let j = 1; j <= n; ++j)
    dp[i][j] = Math.min(
      dp[i - 1][j - 1] + (WORD_A[i - 1] === WORD_B[j - 1] ? 0 : 1),
      dp[i - 1][j] + 1,
      dp[i][j - 1] + 1
    );

const dpMatrix = dp;
const DISTANCE = dp[m][n];
const DP_MAX = Math.max(...dp.flat());

type EditOp = 'match' | 'sub' | 'del' | 'ins';

interface TraceStep {
  i: number;
  j: number;
  op: EditOp;
  /** One aligned column: a letter or a gap on each side. */
  top: string;
  bottom: string;
}

/** Corner back to the origin, diagonal moves preferred so the alignment reads cleanly. */
const steps: TraceStep[] = [];
let i = m;
let j = n;
while (i > 0 || j > 0) {
  const diagonal =
    i > 0 && j > 0 && dp[i][j] === dp[i - 1][j - 1] + (WORD_A[i - 1] === WORD_B[j - 1] ? 0 : 1);
  if (diagonal) {
    const op: EditOp = WORD_A[i - 1] === WORD_B[j - 1] ? 'match' : 'sub';
    steps.push({ i, j, op, top: WORD_A[i - 1], bottom: WORD_B[j - 1] });
    --i;
    --j;
  } else if (i > 0 && dp[i][j] === dp[i - 1][j] + 1) {
    steps.push({ i, j, op: 'del', top: WORD_A[i - 1], bottom: '·' });
    --i;
  } else {
    steps.push({ i, j, op: 'ins', top: '·', bottom: WORD_B[j - 1] });
    --j;
  }
}

/** traceback[0] is the corner cell; the alignment materializes right to left from it. */
const traceback = steps;

const TICK_MS = 280;
const HOLD_TICKS = 12;
const TB = traceback.length;
const TOTAL = WAVE_COUNT + TB;
const HOT = '#e0538a';
const OP_COLOR = { match: 'var(--text)', sub: HOT, ins: 'var(--muted)', del: 'var(--muted)' };

export default function EditDistanceWavefront({ width }: { width: number }) {
  const cell = Math.max(1, Math.min(width / 13, 44));
  const stripHeight = Math.round(cell * 1.9);
  const blockX = (width - (DP_COLS + 1) * cell) / 2;
  const matrixX = blockX + cell;
  const matrixY = stripHeight + cell;
  const height = Math.round(matrixY + DP_ROWS * cell + 22);

  // The SSR frame is the filled matrix with the full traceback lit; the effect replays.
  const [step, setStep] = useState(TOTAL);

  useEffect(() => {
    setStep(0);
    const id = window.setInterval(
      () => setStep((s) => (s >= TOTAL + HOLD_TICKS ? 0 : s + 1)),
      TICK_MS
    );
    return () => window.clearInterval(id);
  }, []);

  const waves = Math.min(step, WAVE_COUNT);
  const traced = Math.max(0, Math.min(step - WAVE_COUNT, TB));

  const traceSet = useMemo(() => {
    const set = new Set<string>();
    for (let k = 0; k < traced; ++k) set.add(`${traceback[k].i},${traceback[k].j}`);
    return set;
  }, [traced]);

  const crestMin = useMemo(() => {
    let best = Infinity;
    for (let i = 0; i < DP_ROWS; ++i) {
      const j = waves - 1 - i;
      if (j >= 0 && j < DP_COLS) best = Math.min(best, dpMatrix[i][j]);
    }
    return best === Infinity ? 0 : best;
  }, [waves]);

  if (width === 0) return null;

  const filling = waves < WAVE_COUNT;
  const alignCell = cell * 0.85;
  const alignX = (width - TB * alignCell) / 2;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Edit distance between INTENTION and EXECUTION filling as a dynamic-programming wavefront: cells complete along anti-diagonals in a visible wave, then the traceback path lights backwards from the corner while the optimal alignment materializes above the matrix, five substitutions ahead of a shared TION tail"
    >
      {traceback.map((stepInfo, k) => {
        const column = TB - 1 - k;
        if (k >= traced) return null;
        return (
          <g key={k} fontFamily="ui-monospace, SFMono-Regular, Menlo, monospace">
            <text
              x={alignX + (column + 0.5) * alignCell}
              y={14 + alignCell * 0.55}
              textAnchor="middle"
              fontSize={alignCell * 0.62}
              fontWeight={600}
              fill={OP_COLOR[stepInfo.op]}
            >
              {stepInfo.top}
            </text>
            <text
              x={alignX + (column + 0.5) * alignCell}
              y={14 + alignCell * 1.5}
              textAnchor="middle"
              fontSize={alignCell * 0.62}
              fontWeight={600}
              fill={OP_COLOR[stepInfo.op]}
            >
              {stepInfo.bottom}
            </text>
          </g>
        );
      })}
      {[...WORD_B].map((letter, k) => (
        <text
          key={k}
          x={matrixX + (k + 1.5) * cell}
          y={matrixY - cell * 0.3}
          textAnchor="middle"
          fontSize={cell * 0.42}
          fontWeight={600}
          fill="var(--muted)"
        >
          {letter}
        </text>
      ))}
      {[...WORD_A].map((letter, k) => (
        <text
          key={k}
          x={matrixX - cell * 0.35}
          y={matrixY + (k + 1.65) * cell}
          textAnchor="middle"
          fontSize={cell * 0.42}
          fontWeight={600}
          fill="var(--muted)"
        >
          {letter}
        </text>
      ))}
      {dpMatrix.map((row, i) =>
        row.map((value, j) => {
          if (i + j >= waves) return null;
          const traceCell = traceSet.has(`${i},${j}`);
          const crest = filling && i + j === waves - 1;
          return (
            <g key={`${i},${j}`}>
              <rect
                x={matrixX + j * cell + 1}
                y={matrixY + i * cell + 1}
                width={cell - 2}
                height={cell - 2}
                rx={2}
                fill={traceCell ? HOT : 'var(--accent)'}
                opacity={traceCell ? 0.65 : crest ? 0.5 : 0.06 + 0.3 * (value / DP_MAX)}
              />
              <text
                x={matrixX + (j + 0.5) * cell}
                y={matrixY + (i + 0.5) * cell + cell * 0.14}
                textAnchor="middle"
                fontSize={cell * 0.38}
                fill="var(--text)"
              >
                {value}
              </text>
            </g>
          );
        })
      )}
      <text x={4} y={height - 6} fill="var(--muted)" fontSize={11}>
        {filling
          ? `filling anti-diagonal ${Math.max(0, waves - 1)} of ${WAVE_COUNT - 1}`
          : traced < TB
            ? `edit distance ${DISTANCE} · tracing the alignment backwards`
            : `${WORD_A} → ${WORD_B} in ${DISTANCE} edits`}
      </text>
      <text x={width - 4} y={height - 6} textAnchor="end" fill="var(--muted)" fontSize={11}>
        {filling ? `distance so far ≥ ${crestMin}` : `distance = ${DISTANCE}`}
      </text>
    </svg>
  );
}
